;BILDSCHIRM-UND DRUCKERAUSGABE;REVISION 4.3;LETZTE BEARBEITUNG 19.02.87;	GLOBAL OUTA;DROUT	EQU	0BE5H;;BILDSCHIRMGROESZE*I POS.TYP;;RAM SPEICHERZELLENMADRR	EQU	0FDEH		;MARKENADRESSREGISTERTSB	EQU	0FDBH	;BITS SIND 0-AKTIV			;BIT 0-3 SELEKORLED'S			;BIT 4 INS-MODE (CAPS ONLY)			;BIT 5 CI (CONTROL)			;BIT 6 HARDCOPY			;BIT 7 HARDCOPY EI;E/A-STEUERZEICHEN*I CTRL.S;DUS	EQU	4HUS	EQU	6;OUTA	PUSH	BC	LD	C,A	LD	A,(TSB)	AND	0C0H	LD	A,C	CALL	Z,DROUT;BILDSCHIRMAUSGABE	PUSH	AF	PUSH	DE	PUSH	HL	LD	HL,EXIT	PUSH	HL	LD	HL,(MADRR)	;HL:=MARKENADRESSE	LD	A,(CHR)	LD	(HL),A;;MARKENADRESSE?	LD	A,(ESCFL)	OR	A	JR	Z,ROLL?;;MARKENADRESSE LADENMXY	DEC	A	LD	(ESCFL),A	RES	7,C	JR	Z,MX	LD	A,LC-1	CP	C	JR	C,MY	LD	A,CMY	LD	HL,BWSA	OR	A	RET	Z	LD	DE,CC	LD	B,AMYM	ADD	HL,DE	DJNZ	MYM	RET;MX	LD	A,CC-1	CP	C	JR	NC,MXOK	LD	C,AMXOK	LD	B,0	ADD	HL,BC	RET;;ROLLADRESSEN?ROLL?	LD	A,(ROLLFL)	OR	A	JP	NZ,SCROLL;NOROLL	LD	A,C	AND	0FCH	CP	ROLL	LD	A,C	JR	NZ,FUNKT?	AND	3	LD	(MODE),A	LD	A,2	LD	(ROLLFL),A	RET;FUNKT?	CP	ESC	JR	Z,SETM	CP	HOME	JR	Z,MHOME	CP	HUS	JR	Z,WRCH	CP	DUS	JR	Z,WRCH	CP	ML	JR	Z,MBS	CP	MR	JR	Z,MRV	CP	LF	JR	Z,MLF	CP	MU	JR	Z,MUP	CP	CR	JR	Z,MCR	CP	CLEAR	JR	Z,DERA	RET	CWRCH;	LD	(HL),A		;<MARKENADR>:=ZKMRV;				MARKE RECHS VERSCHIEBEN	LD	DE,BWSA+CC*LC-1	PUSH	HL	SBC	HL,DE	POP	HL	INC	HL	 ;MARKENADR. IN HL ERHOEHEN	RET	CRON;	LD	HL,BWSA+CC	LD	DE,BWSA	LD	BC,(LC-1)*CC	;BWSA UM EINE ZEILE	LDIR			;NACH OBEN UMSPEICHERN	LD	B,CC		;B:=ZEICHENZAHL PRO ZEILEZL	DEC	HL		;ZEILE LOESCHEN	LD	(HL),' '	DJNZ	ZL	RET;;BILDSCHIRMFUNKTIONEN; SET ESC- FLAGG FOR CURSORPOSITIONSETM	LD	A,2	LD	(ESCFL),A	RET;;BILDSCHIRMLOESCHENDERA;			 GENERALLOESCHEN	LD	BC,CC*LC-1	LD	DE,BWSA+CC*LC-2	LD	HL,BWSA+CC*LC-1	LD	(HL),0	LDDRMHOME;			MARKE AN ANF.	LD	HL,BWSA	RET;MUP;			MARKE NACH OBEN	LD	DE,CC-1	SBC	HL,DEMBS;			 MARKE LINKSVERSCHIEBEN	LD	A,(BWSA.SHR.8)-1	CP	H	JR	Z,MHOME	DEC	HL	RET;MLF;			 MARKE UNTENVERSCHIEBEN	LD	DE,CC-1	ADD	HL,DE	JR	C,RON	JR	MRVMCR;			ZEILENANF.	EX	DE,HL	LD	HL,BWSA+LC*CC-1	LD	BC,CCLB	SBC	HL,BC	PUSH	HL	SBC	HL,DE	POP	HL	JR	NC,LB	INC	HL	RET;;ROLLFUNKTIONEN;PARAMETER LADENSCROLL	DEC	A	LD	(ROLLFL),A	LD	A,C	RES	7,A	JR	Z,GETBIS	LD	(VONZN),A	CALL	CALC	LD	(VONADR),HL	JR	LDMA;GETBIS	LD	HL,VONZN	CP	(HL)	JR	C,LDMA	 ;VONADR>BISADR	CP	LC	JR	NC,LDMA	 ;BISADR>CC	INC	A	CALL	CALC	LD	A,(MODE)	OR	A	JR	Z,ROLRIG	DEC	A	JR	Z,ROLEFT	DEC	A	JR	Z,ROLUPROLDOW	DEC	HL	PUSH	HL	LD	DE,CC	SBC	HL,DE	PUSH	HL	CALL	UP1	INC	BC	POP	HL	POP	DE	JR	LDDR;ROLUP	LD	BC,CC	SBC	HL,BC	CALL	UP1	LD	HL,CC	ADD	HL,DE	JR	LDIR;ROLEFT	CALL	UP1	LD	H,D	LD	L,E	INC	HLLDIR	LDIR	JR	LDMA;ROLRIG	DEC	HL	PUSH	HL	CALL	UP1	POP	DE	LD	H,D	LD	L,E	DEC	HLLDDR	LDDRLDMA	LD	HL,(MADRR)	RET;;UNTERPROGRAMMEUP1	LD	DE,(VONADR)	SBC	HL,DE	LD	B,H	LD	C,L	RET;CALC	LD	HL,BWSA	LD	DE,CCLOOP	OR	A	RET	Z	ADD	HL,DE	DEC	A	JR	LOOP;;TREIBERAUSTRITTEXIT	LD	A,(HL)	LD	(CHR),A	SET	7,(HL)	LD	(MADRR),HL	;MARKENADR.:=HL	POP	HL	POP	DE	POP	AF	POP	BC	RET;VONADR	DEFW	0VONZN	DEFB	0;ESCFL	DEFB	0MODE	DEFB	0ROLLFL	DEFB	0CHR	DEFB	0